defaultDate:
{{
  (() => {
    const debutInitial = Get_Creneau_Detail.data[0]?.Date_Debut;
    const finInitiale = Get_Creneau_Detail.data[0]?.Date_Fin;
    const debutActuel = date_detail_creneau_debut.selectedDate;

    // 1. À l'ouverture de la modale : on conserve la date de fin originale
    if (!debutActuel || debutActuel === debutInitial) {
      return finInitiale || "";
    }

    // 2. Si on modifie la date de début : on conserve la durée initiale du créneau (ex: 30 min, 1 h...)
    const dureeMs = (debutInitial && finInitiale) 
      ? moment(finInitiale).diff(moment(debutInitial)) 
      : 30 * 60 * 1000;

    // 3. On reporte automatiquement cette durée sur la nouvelle date de début
    return moment(debutActuel).add(dureeMs > 0 ? dureeMs : 30, dureeMs > 0 ? 'ms' : 'minutes').toISOString();
  })()
}}
